UPDATE conversation SET last_client_msg_no = (SELECT m.client_msg_no FROM message m WHERE m.channel_id = conversation.channel_id AND m.channel_type = conversation.channel_type AND m.is_deleted = 0 AND m.type <> 0 AND m.type <> 99 AND m.type <> -10 ORDER BY m.order_seq DESC LIMIT 1), last_msg_seq = (SELECT m.message_seq FROM message m WHERE m.channel_id = conversation.channel_id AND m.channel_type = conversation.channel_type AND m.is_deleted = 0 AND m.type <> 0 AND m.type <> 99 AND m.type <> -10 ORDER BY m.order_seq DESC LIMIT 1), last_msg_timestamp = (SELECT m.timestamp FROM message m WHERE m.channel_id = conversation.channel_id AND m.channel_type = conversation.channel_type AND m.is_deleted = 0 AND m.type <> 0 AND m.type <> 99 AND m.type <> -10 ORDER BY m.order_seq DESC LIMIT 1) WHERE EXISTS (SELECT 1 FROM message t WHERE t.client_msg_no = conversation.last_client_msg_no AND t.type = -10) AND EXISTS (SELECT 1 FROM message m WHERE m.channel_id = conversation.channel_id AND m.channel_type = conversation.channel_type AND m.is_deleted = 0 AND m.type <> 0 AND m.type <> 99 AND m.type <> -10);
DELETE FROM message WHERE type = -10;
